# DISCLAIMER: This file is generated by AI for testing purposes.
import unittest

from iSpy.config.schema_fields import (
    completion_for_schema,
    required_setting_keys,
    setting_is_required,
)


class RequiredSettingRuleTests(unittest.TestCase):
    def test_no_default_without_nullable_is_required(self):
        schema = {"ip": {"type": "text", "label": "IP"}}
        self.assertEqual(required_setting_keys(schema, {}), ["ip"])
        self.assertFalse(completion_for_schema(schema, {})["complete"])

    def test_non_blank_default_must_be_confirmed_explicitly(self):
        schema = {"fps": {"type": "number", "default": 30}}
        self.assertEqual(required_setting_keys(schema, {}), ["fps"])
        self.assertFalse(completion_for_schema(schema, {})["complete"])
        self.assertTrue(
            completion_for_schema(schema, {"fps": 30})["complete"]
        )

    def test_blank_default_stays_optional(self):
        schema = {
            "notes": {"type": "text", "default": ""},
            "regions": {"type": "list", "default": []},
        }
        self.assertEqual(required_setting_keys(schema, {}), [])
        self.assertTrue(completion_for_schema(schema, {})["complete"])

    def test_nullable_field_is_optional_even_without_default(self):
        schema = {"dataset": {"type": "browse", "nullable": True}}
        self.assertFalse(setting_is_required(schema, "dataset", {}))

    def test_explicit_required_overrides_default_and_nullable(self):
        schema = {
            "model": {
                "type": "model",
                "default": "",
                "nullable": True,
                "required": True,
            },
            "notes": {"type": "text", "required": False},
        }
        self.assertEqual(required_setting_keys(schema, {}), ["model"])
        self.assertTrue(setting_is_required(schema, "model", {}))

    def test_core_artifact_types_are_required_even_with_empty_default(self):
        for stype in ("model", "source", "browse"):
            schema = {"target": {"type": stype, "default": ""}}
            self.assertTrue(setting_is_required(schema, "target", {}))
            self.assertFalse(completion_for_schema(schema, {})["complete"])

    def test_empty_required_select_and_list_are_incomplete(self):
        schema = {
            "mode": {"type": "select"},
            "regions": {"type": "list"},
        }
        payload = completion_for_schema(schema, {"mode": "", "regions": []})
        self.assertEqual(payload["missing"], ["mode", "regions"])
        self.assertEqual(payload["percent"], 0)
        self.assertFalse(payload["complete"])

        complete = completion_for_schema(
            schema, {"mode": "manual", "regions": [{"name": "field"}]}
        )
        self.assertTrue(complete["complete"])

    def test_empty_model_dict_is_incomplete(self):
        schema = {"vision_model": {"type": "model", "default": ""}}
        payload = completion_for_schema(
            schema, {"vision_model": {"file_path": "", "source_pt": ""}}
        )
        self.assertFalse(payload["complete"])
        self.assertEqual(payload["missing"], ["vision_model"])
        self.assertEqual(payload["percent"], 0)

    def test_model_dict_with_a_path_is_complete(self):
        schema = {"vision_model": {"type": "model", "default": ""}}
        payload = completion_for_schema(
            schema, {"vision_model": {"file_path": "YoloModels/pytorch/a.pt"}}
        )
        self.assertTrue(payload["complete"])
        self.assertEqual(payload["percent"], 100)

    def test_zero_required_fields_are_immediately_complete(self):
        payload = completion_for_schema(
            {"preset": {"type": "select", "default": ""}}, {}
        )
        self.assertEqual(payload["required"], [])
        self.assertEqual(payload["total"], 0)
        self.assertEqual(payload["percent"], 100)
        self.assertTrue(payload["complete"])

    def test_inactive_gated_field_is_optional(self):
        schema = {
            "quantize": {
                "type": "toggle",
                "default": False,
                "required": False,
            },
            "dataset": {
                "type": "browse",
                "default": "",
                "gated_by": "quantize",
            },
        }
        off = completion_for_schema(schema, {"quantize": False})
        self.assertEqual(off["required"], [])
        self.assertTrue(off["complete"])

        on = completion_for_schema(schema, {"quantize": True})
        self.assertEqual(on["required"], ["dataset"])
        self.assertFalse(on["complete"])

    def test_inactive_gate_does_not_require_a_non_blank_default(self):
        schema = {
            "quantize": {"type": "toggle", "default": True},
            "dataset": {
                "type": "browse",
                "default": "datasets/",
                "gated_by": "quantize",
            },
        }
        # The default is truthy, so the gate is active and both non-blank
        # defaults have to be confirmed by an explicit settings value.
        payload = completion_for_schema(schema, {})
        self.assertEqual(payload["required"], ["quantize", "dataset"])

    def test_required_progress_counts_only_required_fields(self):
        schema = {
            "model": {"type": "model", "default": ""},
            "confidence": {"type": "number", "default": 0.5},
            "api_key": {"type": "text", "required": True},
        }
        payload = completion_for_schema(
            schema,
            {
                "model": {"file_path": "YoloModels/pytorch/a.pt"},
                "confidence": 0.9,
            },
        )
        self.assertEqual(payload["required"], ["model", "confidence", "api_key"])
        self.assertEqual(payload["done"], 2)
        self.assertEqual(payload["total"], 3)
        self.assertEqual(payload["percent"], 67)
        self.assertFalse(payload["complete"])

    def test_default_is_not_used_for_completion_until_confirmed(self):
        schema = {"source": {"type": "source", "default": 0}}
        self.assertFalse(completion_for_schema(schema, {})["complete"])
        self.assertFalse(
            completion_for_schema(schema, {"source": ""})["complete"]
        )
        self.assertTrue(
            completion_for_schema(schema, {"source": 0})["complete"]
        )

    def test_missing_labels_follow_schema_labels(self):
        schema = {
            "camera_ip": {
                "type": "text",
                "label": "Camera IP",
                "required": True,
            }
        }
        payload = completion_for_schema(schema, {})
        self.assertEqual(payload["missing"], ["camera_ip"])
        self.assertEqual(payload["missing_labels"], ["Camera IP"])


if __name__ == "__main__":
    unittest.main()
